<?php
require_once '../includes/verificar_admin.php';
require_once '../includes/registro_agentes.php';
require_once '../includes/multiagentes.php';
preparar_registro_agentes($conexion);
$rol=$_SESSION['rol'];$actor=(int)$_SESSION['id_usuario'];
$tabs=$rol==='administrador'?['inventario'=>'Inventario','proveedores'=>'Proveedores','compras'=>'Reposición','devoluciones'=>'Devoluciones','equipo'=>'Equipo y permisos','resumen'=>'Resumen diario']:($rol==='almacen'?['inventario'=>'Inventario','compras'=>'Recepciones','devoluciones'=>'Devoluciones']:['devoluciones'=>'Devoluciones']);
$tab=is_string($_GET['tab']??null)&&isset($tabs[$_GET['tab']])?$_GET['tab']:array_key_first($tabs);$error='';$aviso=$_SESSION['gestion_aviso']??'';unset($_SESSION['gestion_aviso']);
try{
    if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
        exigir_post();$accion=is_string($_POST['accion']??null)?$_POST['accion']:'';
        if(!permite_gestion($rol,$accion))throw new InvalidArgumentException('Tu rol no permite realizar esta operación.');
        $nonce=is_string($_POST['operacion']??null)?$_POST['operacion']:'';if(!isset($_SESSION['gestion_operaciones'][$nonce]))throw new InvalidArgumentException('Formulario utilizado o vencido. Recarga antes de continuar.');
        switch($accion){
            case 'proveedor':$proveedorId=proveedor_gestion($conexion,$_POST);$esAltaProveedor=empty($_POST['id']);break;
            case 'crear_compra':crear_reposicion($conexion,$_POST,$actor);break;
            case 'recibir':recibir_reposicion($conexion,(string)($_POST['id']??''),entero_gestion($_POST['cantidad']??''),(string)($_POST['referencia']??''),$actor);break;
            case 'cancelar_compra':cancelar_reposicion($conexion,(string)($_POST['id']??''),(string)($_POST['motivo']??''),$actor);break;
            case 'ajustar':ajustar_stock_gestion($conexion,entero_gestion($_POST['producto']??'',1,2147483647),entero_gestion($_POST['stock']??'',0,2147483647),(string)($_POST['motivo']??''),$actor);break;
            case 'solicitar_devolucion':solicitar_devolucion($conexion,$_POST,$actor);break;
            case 'resolver_devolucion':if(!in_array($_POST['decision']??'',['recibir','rechazar'],true))throw new InvalidArgumentException('Decisión no válida.');resolver_devolucion($conexion,(string)($_POST['id']??''),$_POST['decision']==='recibir',isset($_POST['reintegrar']),$actor,(string)($_POST['observacion']??''));break;
            case 'reembolso':registrar_reembolso($conexion,(string)($_POST['id']??''),precio_centimos((string)($_POST['importe']??'')),(string)($_POST['referencia']??''),$actor);break;
            case 'crear_usuario':crear_usuario_equipo($conexion,$_POST,$actor);break;
            case 'rol':asignar_rol($conexion,entero_gestion($_POST['usuario']??'',1,2147483647),(string)($_POST['rol']??''),$actor);break;
            case 'usuario_activo':if(!in_array($_POST['activo']??'',['0','1'],true))throw new InvalidArgumentException('Estado de usuario inválido.');activar_usuario_equipo($conexion,entero_gestion($_POST['usuario']??'',1,2147483647),$_POST['activo']==='1',$actor);break;
            case 'resumen':configuracion_gestion($conexion,'resumen_hora',(string)entero_gestion($_POST['hora']??'',0,23));configuracion_gestion($conexion,'resumen_activo',isset($_POST['activo'])?'1':'0');if(!configuracion_gestion($conexion,'resumen_desde'))configuracion_gestion($conexion,'resumen_desde',date('Y-m-d',strtotime('+1 day')));break;
            default:throw new InvalidArgumentException('Operación desconocida.');
        }
        unset($_SESSION['gestion_operaciones'][$nonce]);
        $avisoProveedor='';
        if($accion==='proveedor'&&$esAltaProveedor){
            try{$entrega=enviar_alertas_operativas($conexion,null,null,1,'proveedor-alta-'.$proveedorId);$avisoProveedor=$entrega['enviadas']?' Telegram aceptó el aviso del nuevo proveedor.':' El aviso está registrado; revisa su entrega en Agentes y alertas.';}
            catch(Throwable $e){error_log('Proveedor guardado; aviso pendiente en la cola.');$avisoProveedor=' El aviso quedó pendiente para su revisión automática.';}
        }
        if(in_array($accion,['recibir','ajustar','resolver_devolucion'],true))try{enviar_alertas_operativas($conexion,null,null,1);}catch(Throwable $e){error_log('Gestión guardada; aviso de inventario pendiente en la cola.');}
        $mensajes=['proveedor'=>'Proveedor guardado.','crear_compra'=>'Orden interna registrada. El stock aumentará al recibir las unidades.','recibir'=>'Recepción registrada y existencias actualizadas.','cancelar_compra'=>'Saldo pendiente cancelado. Se conservan las unidades ya recibidas.','ajustar'=>'Ajuste de inventario registrado con su motivo.','solicitar_devolucion'=>'Solicitud de devolución registrada.','resolver_devolucion'=>'Decisión de devolución registrada.','reembolso'=>'Registro del reembolso externo guardado. No se ha ejecutado una transferencia.','crear_usuario'=>'Acceso del equipo creado con el rol seleccionado.','rol'=>'Permisos actualizados. Se aplican en la siguiente solicitud.','resumen'=>'Programación del resumen diario guardada.'];
        $_SESSION['gestion_aviso']=($mensajes[$accion]??'Estado del usuario actualizado. Los accesos se verifican en cada solicitud.').$avisoProveedor;header('Location: gestion.php?tab='.urlencode($tab),true,303);exit;
    }
    if($rol==='administrador'&&configuracion_gestion($conexion,'resumen_activo')===null){configuracion_gestion($conexion,'resumen_activo','1');configuracion_gestion($conexion,'resumen_hora','9');configuracion_gestion($conexion,'resumen_desde',date('Y-m-d',strtotime('+1 day')));}
}catch(Throwable $e){error_log('Gestión comercial: '.$e->getMessage());$error=$e instanceof InvalidArgumentException||($e instanceof RuntimeException&&!($e instanceof PDOException))?$e->getMessage():'No se pudo guardar: verifica que el correo, referencia o registro no estén duplicados.';}
function formulario_gestion(string $accion): string {
    $nonce=bin2hex(random_bytes(16));$_SESSION['gestion_operaciones'][$nonce]=time();if(count($_SESSION['gestion_operaciones'])>400)array_shift($_SESSION['gestion_operaciones']);
    return csrf_campo().'<input type="hidden" name="accion" value="'.e($accion).'"><input type="hidden" name="operacion" value="'.$nonce.'">';
}
$productos=$conexion->query('SELECT id_producto,codigo,nombre,stock FROM productos ORDER BY nombre')->fetchAll(PDO::FETCH_ASSOC);
function opciones_productos_gestion(array $productos): void {foreach($productos as $p)echo '<option value="'.(int)$p['id_producto'].'"'.((string)$p['id_producto']===(string)($_GET['producto']??'')?' selected':'').'>#'.(int)$p['id_producto'].' · '.e($p['nombre']).' · Stock '.(int)$p['stock'].'</option>';}
$proveedores=$rol==='administrador'||$rol==='almacen'?$conexion->query('SELECT * FROM proveedores ORDER BY nombre')->fetchAll(PDO::FETCH_ASSOC):[];
?>
