<section class="ops-section"><h2>Órdenes y recepciones</h2><?php $ordenes=$conexion->query('SELECT c.*,p.nombre producto,v.nombre proveedor_nombre FROM compras_reposicion c JOIN productos p ON p.id_producto=c.id_producto JOIN proveedores v ON v.id=c.proveedor ORDER BY c.creada DESC,c.id DESC LIMIT 40')->fetchAll(PDO::FETCH_ASSOC); ?><div class="ops-actions"><?php foreach($ordenes as $c): ?><article class="ops-action"><h3><?= e($c['producto']) ?></h3><p><?= e($c['proveedor_nombre']) ?> · <?= e($c['estado']) ?><br>Recibido <?= (int)$c['recibida'] ?> de <?= (int)$c['cantidad'] ?> · S/ <?= number_format($c['costo']/100,2) ?> / unidad<br>Creada <?= e($c['creada']) ?> · plazo <?= (int)$c['plazo'] ?> días<br>Orden <?= e($c['id']) ?></p><?php if(in_array($c['estado'],['Solicitada','Parcial'],true)): ?><details><summary>Recibir unidades</summary><form method="POST" class="gestion-form"><?= formulario_gestion('recibir') ?><input type="hidden" name="id" value="<?= e($c['id']) ?>"><label>Unidades recibidas<input name="cantidad" type="number" min="1" max="<?= $c['cantidad']-$c['recibida'] ?>" required></label><label>Referencia única de entrega<input name="referencia" minlength="3" maxlength="150" required placeholder="Guía, factura o acta de recepción"></label><button>Confirmar recepción física</button></form></details><?php if($rol==='administrador'): ?><details><summary>Cancelar lo pendiente</summary><form method="POST" class="gestion-form"><?= formulario_gestion('cancelar_compra') ?><input type="hidden" name="id" value="<?= e($c['id']) ?>"><label>Motivo<input name="motivo" minlength="5" maxlength="500" required></label><button>Cancelar saldo pendiente</button></form></details><?php endif; ?><?php endif; ?></article><?php endforeach; ?></div><?php if(!$ordenes): ?><p>No hay órdenes todavía. Registra un proveedor y crea la primera orden de reposición.</p><?php endif; ?></section>
