<section class="ops-section"><h2>Seguimiento de devoluciones</h2><?php $devs=$conexion->query('SELECT d.*,p.nombre,r.importe,r.referencia FROM devoluciones d JOIN productos p ON p.id_producto=d.id_producto LEFT JOIN reembolsos r ON r.devolucion=d.id ORDER BY d.creada DESC,d.id DESC LIMIT 40')->fetchAll(PDO::FETCH_ASSOC); ?><div class="ops-actions"><?php foreach($devs as $d): ?><article class="ops-action"><h3>Pedido #<?= (int)$d['id_pedido'] ?> · <?= e($d['nombre']) ?></h3><p><?= e($d['estado']) ?> · <?= (int)$d['cantidad'] ?> unidades<br><?= e($d['motivo']) ?><br>Stock reintegrado: <?= $d['reintegrada']?'Sí':'No' ?> · Máximo reembolsable S/ <?= number_format($d['maximo']/100,2) ?></p>
