<?php if($d['importe']!==null): ?><p>Reembolso externo registrado: S/ <?= number_format($d['importe']/100,2) ?> · <?= e($d['referencia']) ?></p><?php elseif($d['estado']==='Recibida'&&$rol==='administrador'): ?><details><summary>Registrar reembolso ya realizado</summary><p>No se ejecuta ninguna transferencia. Registra solo una devolución de dinero realizada fuera del sistema; no incluye envío.</p><form method="POST" class="gestion-form"><?= formulario_gestion('reembolso') ?><input type="hidden" name="id" value="<?= e($d['id']) ?>"><label>Importe (S/)<input name="importe" type="number" min="0.01" max="<?= number_format($d['maximo']/100,2,'.','') ?>" step="0.01" required></label><label>Referencia de operación externa<input name="referencia" minlength="5" maxlength="150" required></label><button>Guardar registro de reembolso</button></form></details><?php endif; ?></article><?php endforeach; ?></div><?php if(!$devs): ?><p>No hay devoluciones registradas.</p><?php endif; ?></section>
<?php elseif($tab==='equipo'): ?>
<section class="ops-section"><h2>Accesos del equipo</h2><p>Administrador: gestión completa. Vendedor: pedidos, clientes y solicitudes de devolución. Almacén: ajustes, recepciones y recepción de devoluciones. Los permisos se verifican en el servidor en cada solicitud.</p><details><summary>Crear usuario del equipo</summary><form method="POST" class="gestion-form"><?= formulario_gestion('crear_usuario') ?><label>Nombre<input name="nombre" minlength="2" maxlength="100" required></label><label>Correo<input name="correo" type="email" maxlength="100" required></label><label>Contraseña inicial<input name="password" type="password" minlength="12" maxlength="200" autocomplete="new-password" required></label><label>Rol<select name="rol"><option value="vendedor">Vendedor</option><option value="almacen">Almacén</option><option value="administrador">Administrador</option></select></label><button>Crear acceso</button></form></details>
<?php $usuarios=$conexion->query('SELECT u.id_usuario,u.nombre,u.correo,u.estado,COALESCE(r.rol,u.rol) rol FROM usuarios u LEFT JOIN usuarios_roles r ON r.id_usuario=u.id_usuario ORDER BY u.id_usuario')->fetchAll(PDO::FETCH_ASSOC); ?><div class="ops-table"><table><thead><tr><th>Usuario</th><th>Correo</th><th>Rol actual</th><th>Cambiar permisos</th></tr></thead><tbody><?php foreach($usuarios as $u): ?><tr><td><?= e($u['nombre']) ?> #<?= (int)$u['id_usuario'] ?></td><td><?= e($u['correo']) ?></td><td><?= e($u['rol']) ?><?= !$u['estado']?' · Inactivo':'' ?></td><td><?php if($u['estado']): ?><form method="POST" class="gestion-inline"><?= formulario_gestion('rol') ?><input type="hidden" name="usuario" value="<?= (int)$u['id_usuario'] ?>"><select name="rol" aria-label="Rol para <?= e($u['nombre']) ?>"><?php foreach(['administrador','vendedor','almacen'] as $r): ?><option <?= $r===$u['rol']?'selected':'' ?>><?= e($r) ?></option><?php endforeach; ?></select><button>Guardar rol</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><p>Se conserva al menos un administrador activo. No cambies tu rol sin disponer de otro administrador.</p></section>
<section class="ops-section"><h2>Activar o desactivar accesos</h2><p>Una cuenta desactivada pierde el acceso en su siguiente solicitud. No se elimina su historial.</p><form method="POST" class="gestion-form"><?= formulario_gestion('usuario_activo') ?><label>Usuario<select name="usuario"><?php foreach($usuarios as $u): ?><option value="<?= (int)$u['id_usuario'] ?>"><?= e($u['nombre']) ?> · <?= $u['estado']?'Activo':'Inactivo' ?></option><?php endforeach; ?></select></label><label>Nuevo estado<select name="activo"><option value="1">Activo</option><option value="0">Inactivo</option></select></label><button>Actualizar acceso</button></form></section>
<?php elseif($tab==='resumen'): ?>
<section class="ops-section"><h2>Resumen diario por Telegram</h2><p>Una vez al día, después de la hora elegida, se encola el resumen del día anterior cerrado: pedidos, importes confirmados y reembolsos registrados, además del stock bajo y pendientes actuales. Usa el bot que ya tienes vinculado.</p><form method="POST" class="gestion-form"><?= formulario_gestion('resumen') ?><label class="check"><input name="activo" type="checkbox" <?= configuracion_gestion($conexion,'resumen_activo')==='1'?'checked':'' ?>> Activar resumen diario</label><label>Hora de Perú (0–23)<input name="hora" type="number" min="0" max="23" value="<?= e(configuracion_gestion($conexion,'resumen_hora')??'9') ?>" required></label><button>Guardar programación</button></form><p>Primer día habilitado: <?= e(configuracion_gestion($conexion,'resumen_desde')) ?>. El envío ocurre en la siguiente ejecución de los agentes posterior a la hora elegida; requiere XAMPP y el programador activos. Si Telegram falla, se conserva en la cola con el manejo de reintentos existente.</p>
<?php $resumenes=$conexion->query("SELECT creada,estado,intento FROM alertas_operativas WHERE tipo='resumen_diario' ORDER BY creada DESC LIMIT 10")->fetchAll(PDO::FETCH_ASSOC); ?><div class="ops-table"><table><thead><tr><th>Creado</th><th>Estado</th><th>Último intento</th></tr></thead><tbody><?php foreach($resumenes as $r): ?><tr><td><?= e($r['creada']) ?></td><td><?= e($r['estado']) ?></td><td><?= e($r['intento']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php endif; ?>
<?php if(in_array($tab,['devoluciones','compras'],true)): ?><section class="ops-section"><details><summary>Últimas decisiones de recepción y cancelación</summary><?php $eventos=$conexion->query('SELECT * FROM gestion_eventos ORDER BY fecha DESC,id DESC LIMIT 20')->fetchAll(PDO::FETCH_ASSOC); ?><div class="ops-table"><table><thead><tr><th>Fecha</th><th>Operación</th><th>Motivo</th><th>Usuario</th></tr></thead><tbody><?php foreach($eventos as $r): ?><tr><td><?= e($r['fecha']) ?></td><td><?= e($r['tipo']) ?> · <?= e($r['referencia']) ?></td><td><?= e($r['motivo']) ?></td><td>#<?= (int)$r['usuario'] ?></td></tr><?php endforeach; ?></tbody></table></div></details></section><?php endif; ?>
<?php if($tab==='equipo'): ?><section class="ops-section"><details><summary>Historial de cambios de permisos</summary><?php $eventos=$conexion->query('SELECT * FROM roles_historial ORDER BY fecha DESC,id DESC LIMIT 30')->fetchAll(PDO::FETCH_ASSOC); ?><div class="ops-table"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Cambio aplicado</th><th>Administrador responsable</th></tr></thead><tbody><?php foreach($eventos as $r): ?><tr><td><?= e($r['fecha']) ?></td><td>#<?= (int)$r['usuario'] ?></td><td><?= e($r['rol']) ?></td><td>#<?= (int)$r['actor'] ?></td></tr><?php endforeach; ?></tbody></table></div></details></section><?php endif; ?>
</main></div></body></html>
